import java.util.*;public class Codec{public String encode(List<String>s){StringBuilder r=new StringBuilder();for(String x:s)r.append(x.length()).append('#').append(x);return r.toString();}public List<String> decode(String s){List<String>o=new ArrayList<>();for(int i=0;i<s.length();){int j=i;while(s.charAt(j)!='#')j++;int n=Integer.parseInt(s.substring(i,j));o.add(s.substring(j+1,j+1+n));i=j+1+n;}return o;}}
